CREATE DATABASE customer_behaviour;
USE customer_behaviour;
SELECT*FROM customer_shopping_behavior LIMIT 10;
-- what is the total revenue generated by male vs female customers?
SELECT gender, SUM(purchased_amount) AS revenue
FROM customer_shopping_behavior
GROUP BY gender;
-- which customer used discount still spent more than avg purchase amount?
SELECT customer_id, discount_applied, purchased_amount
FROM customer_shopping_behavior
WHERE discount_applied = 'Yes' AND purchased_amount >= (SELECT AVG(purchased_amount) FROM customer_shopping_behavior);
-- which are the top 5 products with highest rating review
SELECT item_purchased, ROUND(AVG(review_rating),2) AS 'avg_rating'
FROM customer_shopping_behavior
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC LIMIT 5;
-- compare the average purchase amounts between standard and express shipping
 SELECT shipping_type, AVG(purchased_amount)
 FROM customer_shopping_behavior
 WHERE shipping_type IN ('Express','Standard')
 GROUP BY shipping_type
 -- Do subscribed customers spend more? compare total spend and avg spend between subscribed and non-subscribed customers
SELECT SUM(purchased_amount) AS total_revenue, AVG(purchased_amount) AS avg_revenue, subscription_status
 FROM customer_shopping_behavior
 GROUP BY subscription_status;
 -- which 5 products have the highest percentage of purchases with discounts applied?
 SELECT item_purchased, ROUND(SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/ COUNT(*) * 100, 2) AS discount_rate
 FROM customer_shopping_behavior
 GROUP BY item_purchased
 ORDER BY discount_rate DESC
 LIMIT 5;
 -- segment customers into new, returning, loyal based on their previous purchases and show count of each segment
 SELECT COUNT(customer_id) AS number_of_customers, 
 CASE WHEN previous_purchases <= '1' THEN 'New' 
 WHEN previous_purchases <= '10' THEN 'Returning'
 ELSE 'Loyal' END AS customer_segment
 FROM customer_shopping_behavior
 GROUP BY customer_segment;
 -- what are the top 3 most purchased products within each category
WITH cal AS (SELECT category, item_purchased, COUNT(customer_id) AS total_orders,
ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
FROM customer_shopping_behavior
GROUP BY category, item_purchased) SELECT category, item_purchased, total_orders, item_rank
FROM cal WHERE item_rank <= 3;
-- are customers who are repeat buyers are likely to subscribe? (more than 5 purchases)
SELECT COUNT(customer_id) AS repeaT_buyers, subscription_status
FROM customer_shopping_behavior
WHERE previous_purchases > 5
GROUP BY subscription_status;
-- what is the revenue generated by each revenue
SELECT SUM(purchased_amount) AS total_revenue, age_group
FROM customer_shopping_behavior
GROUP BY age_group
ORDER BY total_revenue DESC;